SELECT mcpawcl.*, ssc.classification_name as artifact_type_name, mbp.id AS process_id, mbp.name AS process_name FROM mes_contract_project_assembling_welding_config_link mcpawcl LEFT JOIN sys_structure_classification ssc on ssc.bool_delete_enum = FALSE and ssc.id = mcpawcl.artifact_type_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mcpawcl.process) > 0 WHERE mcpawcl.bool_delete_enum = FALSE
AND mcpawcl.contract_project_id in (
#{i}
)

SELECT mcpawcl.*, ssc.classification_name as artifact_type_name, mbp.id AS process_id, mbp.name AS process_name FROM mes_contract_project_assembling_welding_config_link mcpawcl LEFT JOIN sys_structure_classification ssc on ssc.bool_delete_enum = FALSE and ssc.id = mcpawcl.artifact_type_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mcpawcl.process) > 0 WHERE mcpawcl.bool_delete_enum = FALSE
AND mcpawcl.id in (
#{i}
)

SELECT mcpawcl.*, ssc.classification_name as artifact_type_name, mbp.id AS process_id, mbp.name AS process_name FROM mes_contract_project_assembling_welding_config_link mcpawcl LEFT JOIN sys_structure_classification ssc on ssc.bool_delete_enum = FALSE and ssc.id = mcpawcl.artifact_type_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mcpawcl.process) > 0 WHERE mcpawcl.bool_delete_enum = FALSE
AND mcpawcl.contract_project_id = #{param.projectId}
AND mcpawcl.artifact_type_id = #{param.artifactTypeId}
AND FIND_IN_SET(#{param.artifactName}, mcpawcl.artifact) > 0
AND FIND_IN_SET(#{param.processId}, mcpawcl.process) > 0
